// Prose freshness: the hand-authored documents, checked against the generated reports.
//
// WHY THIS EXISTS. README.md, MEMO.md and docs/*.md are the only files in this repository that a
// human types numbers into. Everything under reports/ is regenerated by `node dist/cli.js all` and
// diffed by scripts/verify-reports.mjs, so a generated number cannot silently drift. A number
// retyped into prose can, and did: an audit found 24 drifted figures across these three documents,
// including a package hash that no package produced any more, counted-trial counts for families
// with zero counted trials, and a cross-lab result whose every trial had been superseded.
//
// WHY IT IS HERE RATHER THAN IN `pnpm verify`. `pnpm verify` regenerates every report through the
// CLI and takes over ten minutes on a developer machine. A ten-minute check is a check people learn
// to skip, and the drift this file guards against is introduced by editing prose — the cheapest,
// most frequent, least ceremonious edit anyone makes here. So the expensive whole-repository
// reproduction runs in CI (.github/workflows/verify.yml, which always runs and cannot be skipped)
// and this file runs in `pnpm test`, where it costs a few milliseconds because it only reads files.
//
// WHAT IT CAN AND CANNOT CATCH. It is not a general fact-checker. It enforces three properties:
//
//   1. Every challenge hash quoted in prose is a hash some report currently prints.
//   2. Claims that depend on counted trials are absent from prose while the generated report says
//      the family has no counted trials. These rules ARM AND DISARM from the report, so they are
//      not a hardcoded blocklist: publish a counted trial and the rule stops applying by itself.
//   3. The specific figures prose still quotes equal the figures the report currently states.
//
// Everything else was deleted from prose rather than checked, which is the cheaper fix: a number
// that is not written down cannot drift. Rule 3's table is deliberately short for that reason, and
// the right response to a failure in it is usually to delete the sentence and link the report.

import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

const ROOT = join(import.meta.dirname, "..");
const PROSE_FILES = [
  "README.md",
  "MEMO.md",
  ...readdirSync(join(ROOT, "docs"))
    .filter((f) => f.endsWith(".md"))
    .map((f) => join("docs", f)),
];

const read = (rel: string): string => readFileSync(join(ROOT, rel), "utf8");
const report = (name: string): string => read(join("reports", name));

/** Every prose file, as one string per file, so a failure can name the file it came from. */
const prose: readonly (readonly [string, string])[] = PROSE_FILES.map((f) => [f, read(f)] as const);

/**
 * The concatenation of every generated report.
 *
 * Used only for existence questions ("is this hash still printed anywhere?"). Never for extracting
 * a value — a value is always pulled from one named report, so the assertion says which generator
 * owns the number.
 */
const allReports = (): string =>
  readdirSync(join(ROOT, "reports"))
    .filter((f) => f.endsWith(".md"))
    .map((f) => report(f))
    .join("\n");

// ---------------------------------------------------------------------------------------------
// 1. Hashes
// ---------------------------------------------------------------------------------------------

/**
 * The set of package hashes that are CURRENT — the ones a family produces today.
 *
 * Deliberately not "every hash any report mentions": the superseded-trial tables print the old
 * hashes on purpose, so an existence check against all reports would happily pass a hash that was
 * replaced. It is precisely a replaced hash that prose must not quote.
 *
 * Two sources, both authoritative and both regenerated: the `package hash` column of the
 * adversarial audit report (one row per package-backed family) and every `| challenge hash |` row
 * in the per-family reports.
 */
function currentHashes(): ReadonlySet<string> {
  const set = new Set<string>();
  for (const m of report("adversarial-audit-report.md").matchAll(
    /^\| `[^`]+` \| \*\*[^*]+\*\* \| `([0-9a-f]{32})` \|/gm,
  )) {
    set.add(m[1] as string);
  }
  for (const f of readdirSync(join(ROOT, "reports")).filter((n) => n.endsWith(".md"))) {
    for (const m of report(f).matchAll(/^\| challenge hash \| `([0-9a-f]{32})` \|/gm)) {
      set.add(m[1] as string);
    }
  }
  return set;
}

describe("prose quotes no stale challenge hash", () => {
  // A challenge hash is the mechanism that stops a trial counting once the package changes. Prose
  // that names a replaced hash is claiming a result about a task that no longer exists, which is
  // the exact failure the hash was introduced to prevent. Five stale package hashes and three
  // stale in-body hashes were live in this repository when this check was written.
  it("every 32-hex hash in prose is a hash some family currently produces", () => {
    const current = currentHashes();
    expect(
      current.size,
      "no current package hashes found — the extractor has drifted from the report format",
    ).toBeGreaterThan(3);
    const stale: string[] = [];
    for (const [file, text] of prose) {
      for (const m of text.matchAll(/`([0-9a-f]{32})`/g)) {
        const hash = m[1] as string;
        if (!current.has(hash)) stale.push(`${file}: ${hash}`);
      }
    }
    expect(
      stale,
      [
        "Prose names a package hash that is no longer current. The package was re-hashed, so the",
        "claim attached to that hash is WITHDRAWN, not renumbered — every trial and audit pinned",
        `to it stopped counting the moment it changed:\n  ${stale.join("\n  ")}`,
        `\nCurrent hashes: ${[...current].sort().join(", ")}`,
      ].join(" "),
    ).toEqual([]);
  });
});

// ---------------------------------------------------------------------------------------------
// 2. Claims that need counted trials
// ---------------------------------------------------------------------------------------------

/**
 * Phrases prose may not contain while `family` has no counted agent trial.
 *
 * The rule arms itself off the generated agent-results report rather than off a constant, so it
 * cannot become a stale blocklist: run a counted trial, regenerate, and the rule stops applying.
 * Phrases are matched case-insensitively against the whole file, and every one of them is a
 * sentence that was actually published here and had to be withdrawn.
 */
const COUNTED_TRIAL_CLAIMS: readonly {
  readonly family: string;
  readonly resultsReport: string;
  readonly forbidden: readonly string[];
}[] = [
  {
    family: "prompt-injection-memory-poisoning",
    resultsReport: "prompt-injection-memory-poisoning-agent-results.md",
    forbidden: [
      "failed the identical 32 scenarios",
      "failed the same 32 scenarios across labs",
      "cross-lab failure generalises",
    ],
  },
  {
    family: "access-token-scope-expansion",
    resultsReport: "access-token-scope-expansion-agent-results.md",
    forbidden: ["passed 384 of 384", "passed 384/384", "It passed 384/384"],
  },
  {
    family: "delegated-wallet-scope-reconciliation",
    resultsReport: "delegated-wallet-scope-reconciliation-agent-results.md",
    forbidden: ["passed 804/804", "passed all 804 scenarios cleanly"],
  },
  {
    family: "deployment-model-alias-rollout-drift",
    resultsReport: "deployment-model-alias-rollout-drift-agent-results.md",
    forbidden: [
      "failed 192/339 scenarios on target",
      "imported cleanly and passed\n339/339",
      "OpenAI failed, Claude solved",
    ],
  },
];

/** True when the generated report states, in its own headline, that nothing has attempted it. */
const hasNoCountedTrial = (resultsReport: string): boolean =>
  report(resultsReport).includes("**No counted agent trial exists.**");

describe("prose withdraws claims whose trials no longer count", () => {
  for (const { family, resultsReport, forbidden } of COUNTED_TRIAL_CLAIMS) {
    it(`${family}: no difficulty claim in prose while it has zero counted trials`, () => {
      if (!hasNoCountedTrial(resultsReport)) {
        // The family has counted trials again. The rule disarms rather than fails: a real result
        // is allowed to be written up. Re-read the report before quoting numbers from it.
        expect(report(resultsReport)).toContain("counted agent trial");
        return;
      }
      const found: string[] = [];
      for (const [file, text] of prose) {
        const hay = text.toLowerCase().replace(/\s+/g, " ");
        for (const phrase of forbidden) {
          const needle = phrase.toLowerCase().replace(/\s+/g, " ");
          // A withdrawal notice is allowed to quote the claim it is withdrawing, so the phrase is
          // only a failure outside a blockquote. Lines beginning "> " are the withdrawal blocks.
          const unquoted = text
            .split("\n")
            .filter((l) => !l.trimStart().startsWith(">"))
            .join(" ")
            .toLowerCase()
            .replace(/\s+/g, " ");
          if (hay.includes(needle) && unquoted.includes(needle)) found.push(`${file}: "${phrase}"`);
        }
      }
      expect(
        found,
        [
          `reports/${resultsReport} says ${family} has NO counted agent trial, but prose still`,
          "asserts a result that needed one. A corrected number attached to a withdrawn claim is",
          `still a false claim: withdraw the sentence, do not renumber it.\n  ${found.join("\n  ")}`,
        ].join(" "),
      ).toEqual([]);
    });
  }
});

// ---------------------------------------------------------------------------------------------
// 3. Figures prose still quotes
// ---------------------------------------------------------------------------------------------

/** Pull the value out of a `| label | value |` row, stripping bold markers. */
function tableValue(reportName: string, label: string): string {
  const text = report(reportName);
  const row = text.split("\n").find((l) => l.startsWith(`| ${label} |`) || l.startsWith(`| **${label}** |`));
  if (row === undefined) throw new Error(`reports/${reportName}: no table row labelled "${label}"`);
  const cell = row.split("|")[2];
  if (cell === undefined) throw new Error(`reports/${reportName}: row "${label}" has no value cell`);
  return cell.replace(/\*/g, "").trim();
}

/** First capture group of `pattern` in the named report. */
function captured(reportName: string, pattern: RegExp): string {
  const m = report(reportName).match(pattern);
  if (m?.[1] === undefined) throw new Error(`reports/${reportName}: ${String(pattern)} did not match`);
  return m[1];
}

/**
 * Each entry: a figure prose asserts, and the generated value it must equal.
 *
 * `expect` is what the report currently says; `mustAppearIn` is the file whose prose quotes it;
 * `sentence` is a function of the live value, so when the report moves the assertion fails with the
 * sentence the prose is supposed to contain. Keep this table SHORT — every row is a number someone
 * has to maintain, and deleting the number from prose is always the better repair.
 */
const QUOTED: readonly {
  readonly what: string;
  readonly file: string;
  readonly live: () => string;
  readonly sentence: (v: string) => string;
}[] = [
  {
    what: "counted adversarial no-bypass audits (README)",
    file: "README.md",
    live: () =>
      String(
        (report("adversarial-audit-report.md").match(/^Adversarial-audited families: (.+)$/m)?.[1] ?? "")
          .split(",")
          .filter((s) => s.trim().length > 0).length,
      ),
    sentence: (v) => (v === "2" ? "**Two** real Codex/OpenAI adversarial audits" : `__EXPECT_${v}__`),
  },
  {
    what: "live-DOM counted trial, graded and failed (README)",
    file: "README.md",
    live: () =>
      captured("ui-replay-live-dom-agent-results.md", /\| `live-dom-2026-08-o2` \|[^|]+\|[^|]+\| (\d+) \|/),
    sentence: (v) => `${v} graded scenarios, 219 failed`,
  },
  {
    what: "live-DOM failed-scenario count (README)",
    file: "README.md",
    live: () =>
      captured(
        "ui-replay-live-dom-agent-results.md",
        /\| `live-dom-2026-08-o2` \|[^|]+\|[^|]+\|[^|]+\| (\d+) \|/,
      ),
    sentence: (v) => `864 graded scenarios, ${v} failed`,
  },
  {
    what: "browser-backed measured slice (README)",
    file: "README.md",
    live: () =>
      [
        tableValue("ui-replay-browser-backed-report.md", "measured scenarios"),
        tableValue("ui-replay-browser-backed-report.md", "measured subjects"),
        tableValue("ui-replay-browser-backed-report.md", "measured cells"),
      ].join("/"),
    sentence: (v) => {
      const [s, sub, c] = v.split("/");
      return `has ${s} scenarios, ${sub} subjects, ${c} cells`;
    },
  },
  {
    what: "durable-outbox axis headline (MEMO section 2)",
    file: "MEMO.md",
    live: () => tableValue("durable-outbox-axis-report.md", "independent axes (antichain width)"),
    sentence: (v) => `| **independent axes** (antichain width) | **${v}** |`,
  },
  {
    what: "durable-outbox graded instances (MEMO section 2)",
    file: "MEMO.md",
    live: () => tableValue("durable-outbox-axis-report.md", "graded instances"),
    sentence: (v) => `| graded instances | **${v}** |`,
  },
  {
    what: "SWE-bench independent axes (MEMO headline)",
    file: "MEMO.md",
    live: () => tableValue("public-swebench-verified-axis-report.md", "independent axes (antichain width)"),
    sentence: (v) => `it reports **${v} axes**`,
  },
  {
    what: "budget: families / instances / axes (MEMO section 5)",
    file: "MEMO.md",
    live: () =>
      captured(
        "budget-plan.md",
        /\*\*(\d+) families yielding about (?:\d+) graded instances and (?:\d+) independent axes\*\*/,
      ),
    sentence: (v) => `**${v} families / 168 generated instances / ~21 independent axes**`,
  },
  {
    what: "budget: labour share of spend (MEMO section 5)",
    file: "MEMO.md",
    live: () => captured("budget-plan.md", /\*\*Labour is (\d+)% of spend\.\*\*/),
    sentence: (v) => `with labour at **${v}%** of\nspend`,
  },
  {
    what: "budget: hand-authored task count (MEMO section 5)",
    file: "MEMO.md",
    live: () => captured("budget-plan.md", /^\| hand-authored tasks \| (\d+) \|/m),
    sentence: (v) => `the same money buys **${v} tasks**`,
  },
];

describe("figures prose still quotes match the report that generates them", () => {
  for (const q of QUOTED) {
    it(q.what, () => {
      const live = q.live();
      const expected = q.sentence(live);
      const text = read(q.file).replace(/\s+/g, " ");
      expect(
        text.includes(expected.replace(/\s+/g, " ")),
        [
          `${q.file} should contain "${expected}" — that is what the generated report now says.`,
          "If the report moved, either update the sentence or (better) delete the figure from",
          "prose and link the report.",
        ].join(" "),
      ).toBe(true);
    });
  }
});

// ---------------------------------------------------------------------------------------------
// The guard's own guard
// ---------------------------------------------------------------------------------------------

describe("the freshness check is wired to something that can move", () => {
  it("reads real generated reports, not fixtures", () => {
    expect(report("adversarial-audit-report.md").length).toBeGreaterThan(500);
    expect(PROSE_FILES.length).toBeGreaterThanOrEqual(4);
  });

  it("would fail if prose drifted: the hash guard rejects a superseded hash", () => {
    // Proves rule 1 is not vacuous, and specifically that it is stricter than "mentioned
    // somewhere". `0e9b87a5...` is the deployment-alias hash the starter-leak repair replaced. It
    // still appears in reports — the superseded-trial tables name it on purpose — so a guard that
    // only asked "does any report mention this?" would pass it. It must be rejected.
    const superseded = "0e9b87a5f260544cfbc1cdce8f08938c";
    expect(
      allReports().includes(superseded),
      "the superseded deployment-alias hash should still be mentioned in the trial tables",
    ).toBe(true);
    expect(
      currentHashes().has(superseded),
      "a replaced hash must not be in the current set — otherwise the guard is vacuous",
    ).toBe(false);
    expect(currentHashes().has("deadbeefdeadbeefdeadbeefdeadbeef")).toBe(false);
  });
});
